# 1) Bloc import déclaratif (Terraform 1.5+)
import {
  to = aws_s3_bucket.existant
  id = "mon-bucket-cree-a-la-main"
}

# 2) Écrire (ou faire générer) le code de la ressource
resource "aws_s3_bucket" "existant" {
  bucket = "mon-bucket-cree-a-la-main"
  # ... aligner les attributs sur l'objet réel ...
}

# terraform plan -generate-config-out=genere.tf   (peut générer le code)
# terraform apply    -> importe dans le state, sans recréer

# Déclarer les imports (déclaratif, versionné)
import {
  to = aws_s3_bucket.logs
  id = "org-logs-bucket"
}
import {
  to = aws_s3_bucket.assets
  id = "org-assets-bucket"
}

# Générer le code HCL des ressources importées :
#   terraform plan -generate-config-out=generated.tf
# -> Terraform écrit les blocs resource à partir du réel ; on ajuste, puis apply.
